/* VCD dumping functions */
MOD_mkTbNocBasic & mkTbNocBasic_backing(tSimStateHdl simHdl)
{
  static MOD_mkTbNocBasic *instance = NULL;
  if (instance == NULL)
  {
    vcd_set_backing_instance(simHdl, true);
    instance = new MOD_mkTbNocBasic(simHdl, "top", NULL);
    vcd_set_backing_instance(simHdl, false);
  }
  return *instance;
}
