{
  (mkTbNocBasic_instance->dump_VCD_defs)(vcd_depth(sim_hdl));
}
void MODEL_mkTbNocBasic::dump_VCD(tVCDDumpType dt)
{
  (mkTbNocBasic_instance->dump_VCD)(dt, vcd_depth(sim_hdl), mkTbNocBasic_backing(sim_hdl));
}
